<script setup lang="ts">
import { Container } from '@/shared/ui/container';
import { Heading } from '@/shared/ui/text/heading';
import { Text } from '@/shared/ui/text/paragraph';
import { RouterLink } from 'vue-router';
import { onMounted, computed } from 'vue';
import { useStore } from 'vuex';

const store = useStore();

onMounted(() => {
  store.dispatch('projects/fetchProjects');
});

const projectsData = computed(() => store.state.projects?.projectsData);


const firstFourProjects = computed(() => {
  return projectsData.value ? projectsData.value.slice(0, 4) : [];
});
</script>

<template>
    <section class="section-four">
        <Container>
            <div class="section-four__content">
                <div class="content__header">
                    <Heading tagName="h3" size="s">
                        Реализованные проекты
                    </Heading>
                    <RouterLink to="/projects/">
                        <Text tagName="span" color="accent">Все проекты</Text>
                    </RouterLink>
                </div>
                <div class="content__items">
                    <div class="item" :id="'item' + `${item.id + 1}`" v-for="item in firstFourProjects" :key="item.id">
                        <RouterLink :to="'/projects/' +`${item.slug}`">
                            <img :src="item.image" :alt="item.title">
                            <Text tagName="p" size="xl" color="dark-first">{{ item.title }}</Text>
                        </RouterLink>
                    </div>
                </div>
            </div>
        </Container>
    </section>
    <hr>
</template>

<style lang="scss" scoped>
@import './style.scss';
</style>