<script setup lang="ts">
import { Text } from '@/shared/ui/text/paragraph';
import { Icon } from '@/shared/ui/icons'
import { Button } from '@/shared/ui/button'
import { Container } from '@/shared/ui/container';
import { ref } from 'vue';
import { API_BASE_URL } from '@/shared/api';
import axios from 'axios';

const email = ref('');
const isLoading = ref(false);
const isSuccess = ref(false);
const errorMessage = ref('');

const handleSubmit = async (e: Event) => {
  e.preventDefault();
  
  if (!email.value) {
    errorMessage.value = 'Пожалуйста, введите email';
    return;
  }

  if (!isValidEmail(email.value)) {
    errorMessage.value = 'Пожалуйста, введите корректный email';
    return;
  }

  isLoading.value = true;
  errorMessage.value = '';

  try {
    const response = await axios.post(`${API_BASE_URL}mail`, {
      email: email.value,
      type: 'subscription',
      subject: 'Подписка на новости и акции'
    });

    if (response.status === 200 || response.status === 201) {
      isSuccess.value = true;
      email.value = '';
      // Сбрасываем успешное состояние через 5 секунд
      setTimeout(() => {
        isSuccess.value = false;
      }, 5000);
    }
  } catch (error: any) {
    console.error('Ошибка при отправке формы:', error);
    errorMessage.value = error.response?.data?.message || 'Произошла ошибка при отправке. Попробуйте позже.';
  } finally {
    isLoading.value = false;
  }
};

const isValidEmail = (email: string): boolean => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const resetForm = () => {
  errorMessage.value = '';
  isSuccess.value = false;
};
</script>

<template>
    <section class="section-subscription">
        <Container>
            <div class="section-subscription__content">
                <div class="content-left">
                    <Icon type="subscription" color="gray" class="icon"/>
                    <Text tagName="p" color="white" size="m">Подписывайтесь на новости и акции:</Text>
                </div>
                <Text tagName="p" color="white" size="m" class="content-title">Подписывайтесь на новости и акции:</Text>
                
                <form class="subscription-form" >
                    <div class="input-wrapper">
                        <input 
                            type="email" 
                            placeholder="Email"
                            v-model="email"
                            @input="resetForm"
                            :disabled="isLoading"
                            required
                        >
                        <div v-if="errorMessage" class="error-message">
                            <Text tagName="span" color="red" size="s">
                                {{ errorMessage }}
                            </Text>
                        </div>
                        <div v-if="isSuccess" class="success-message">
                            <Text tagName="span" color="green" size="xxxl">
                                Спасибо за подписку!
                            </Text>
                        </div>
                    </div>
                    
                    <Button 
                        tagName="button" 
                        @click="handleSubmit"
                        :disabled="isLoading || !email"
                        :loading="isLoading"
                    >
                        <Text tagName="span" color="white" size="l">
                            {{ isLoading ? 'Отправка...' : 'Подписаться' }}
                        </Text>
                    </Button>
                </form>
            </div>
        </Container>
    </section>
</template>
<style lang="scss" scoped>
@import './style.scss';
</style>