<script setup lang="ts">
import { Container } from '@/shared/ui/container';
import { Heading } from '@/shared/ui/text/heading';
import { Text } from '@/shared/ui/text/paragraph';
import { RouterLink } from 'vue-router';
import { onMounted, computed } from 'vue';
import { useStore } from 'vuex';

const store = useStore();

onMounted(() => {
    store.dispatch('blogs/fetchBlog');
});

const blogData = computed(() => {
    const data = store.state.blogs?.blogData?.filter((item: any) => item.subject === 'Блог молока')
    return data.map((item: any, index: number) => ({
        ...item,
        index: index
    }));
});

</script>

<template>
    <section class="section-second">
        <Container>
            <div class="section-second__content">
                <div class="content__header">
                    <Heading tagName="h3" size="s">
                        Статьи
                    </Heading>
                    <RouterLink to="/blog/">
                        <Text tagName="span" color="accent">Все статьи</Text>
                    </RouterLink>
                </div>

                <div class="content__items">
                    <div class="item" :id="'item' + `${item.index + 1}`" v-for="(item, index) in blogData" :key="index">
                        <RouterLink :to="'/blog/'+`${item.slug}/`">
                            <img :src="item.image" :alt="item.title">
                            <div class="descripton">
                                <Text tagName="span" size="xs" color="blue">{{ item.category }}</Text>
                                <Text tagName="p" size="xl" color="dark-first" class="title">{{ item.title }}</Text>
                            </div>
                        </RouterLink>
                    </div>
                </div>
            </div>
        </Container>
    </section>
    <hr>
</template>

<style scoped lang="scss">
@import './style.scss';
</style>