import { ref, provide, inject, Ref, onUnmounted } from 'vue';

export const useBurgerMenu = () => {
  const isVisibleMenu = ref(false);
  let scrollPosition = 0;

  const disableBodyScroll = () => {
    // Сохраняем позицию скролла
    scrollPosition = window.pageYOffset || document.documentElement.scrollTop;
    
    document.body.style.overflow = 'hidden';
    document.body.style.position = 'fixed';
    document.body.style.width = '100%';
    document.body.style.top = `-${scrollPosition}px`;
  };

  const enableBodyScroll = () => {
    document.body.style.overflow = '';
    document.body.style.position = '';
    document.body.style.width = '';
    document.body.style.top = '';
    
    // Восстанавливаем позицию скролла
    window.scrollTo(0, scrollPosition);
  };

  const openMenu = () => {
    if (!isVisibleMenu.value) {
      isVisibleMenu.value = true;
      disableBodyScroll();
    }
  };

  const closeMenu = () => {
    if (isVisibleMenu.value) {
      isVisibleMenu.value = false;
      enableBodyScroll();
    }
  };

  onUnmounted(() => {
    if (isVisibleMenu.value) {
      enableBodyScroll();
    }
  });

  provide('isVisibleMenu', isVisibleMenu);
  provide('openMenu', openMenu);
  provide('closeMenu', closeMenu);

  return { isVisibleMenu, openMenu, closeMenu };
};

export const useBurgerMenuInjection = () => {
  const isVisibleMenu = inject('isVisibleMenu') as Ref<boolean>;
  const openMenu = inject('openMenu') as () => void;
  const closeMenu = inject('closeMenu') as () => void;

  return { isVisibleMenu, openMenu, closeMenu };
};